", "founded_year": "1975", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='jordan-manufacturing-co' AND approved AND profile IS NULL;
UPDATE companies SET description='Josephine''s Dry Goods operates a fabric boutique at 2609 SE Clinton Street in Portland, Oregon. The business has been active since at least 2007, as indicated by its copyright notice, and trades under the name Josephine''s Dry Goods.

